    return FfiConverterTypeRegistration.lower(value)
}




/**
 * Une paire de clés X25519, telle qu'elle voyage.
 *
 * La privée est en PKCS#8 et la publique brute, toutes deux en base64 : c'est ce que
 * produit `crypto.subtle.exportKey` côté web, et changer cet encodage rendrait illisible
 * ce qui est déjà stocké.
 */
public struct PaireDeCles {
    public var publique: String
    public var privee: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(publique: String, privee: String) {
        self.publique = publique
        self.privee = privee
    }
}

#if compiler(>=6)
extension PaireDeCles: Sendable {}
#endif


extension PaireDeCles: Equatable, Hashable {
    public static func ==(lhs: PaireDeCles, rhs: PaireDeCles) -> Bool {
        if lhs.publique != rhs.publique {
            return false
        }
        if lhs.privee != rhs.privee {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(publique)
        hasher.combine(privee)
    }
}



