/**
 * Un secret scellé pour être partagé une fois : le serveur stocke `ciphertext` et `nonce`,
 * la clé voyage à part — dans le fragment d'une URL, que les navigateurs n'envoient jamais.
 * Le serveur héberge donc quelque chose qu'il ne peut pas lire.
 */
public struct SealedSend {
    public var ciphertext: String
    public var nonce: String
    /**
     * À placer dans le fragment du lien, jamais dans son chemin ni sa requête.
     */
    public var key: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(ciphertext: String, nonce: String, 
        /**
         * À placer dans le fragment du lien, jamais dans son chemin ni sa requête.
         */key: String) {
        self.ciphertext = ciphertext
        self.nonce = nonce
        self.key = key
    }
}

#if compiler(>=6)
extension SealedSend: Sendable {}
#endif


extension SealedSend: Equatable, Hashable {
    public static func ==(lhs: SealedSend, rhs: SealedSend) -> Bool {
        if lhs.ciphertext != rhs.ciphertext {
            return false
        }
        if lhs.nonce != rhs.nonce {
            return false
        }
        if lhs.key != rhs.key {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(ciphertext)
        hasher.combine(nonce)
        hasher.combine(key)
    }
}



