/**
 * Erreur unique côté FFI.
 *
 * La forme est celle qui tournait déjà chez ghostpass : une variante portant un message.
 * Ce déménagement ne change aucun comportement, et la sémantique des erreurs en fait
 * partie — la resserrer en passant aurait modifié ce que l'application affiche, sans que
 * personne l'ait demandé.
 *
 * Un point reste à trancher, séparément : un message d'erreur cryptographique renseigne
 * autant l'attaquant que l'utilisateur. « la clé privée ne correspond pas à ce sceau »
 * apprend à qui l'obtient qu'il tient un sceau valide. À reprendre quand un produit
 * aura besoin d'un message plus discret — pas au milieu d'un déplacement.
 * Le champ s'appelle `raison` et non `message`, et ce n'est pas un choix de style.
 *
 * UniFFI génère pour Kotlin une classe qui étend `Exception`. Un champ nommé `message`
 * y devient un `val message` en conflit avec celui d'`Exception`, et **le Kotlin produit
 * ne compile pas**. Swift ne s'en émeut pas : le défaut n'existe que du côté qu'on
 * n'avait jamais généré, et il est resté invisible jusqu'à ce qu'on essaie.
 *
 * Aucun appelant Swift ne nomme ce champ — ils lisent tous `localizedDescription` — donc
 * le renommer ne casse rien en aval.
 */
public enum GhostCryptoError: Swift.Error {

    
    
    case Crypto(raison: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeGhostCryptoError: FfiConverterRustBuffer {
    typealias SwiftType = GhostCryptoError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> GhostCryptoError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Crypto(
            raison: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: GhostCryptoError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Crypto(raison):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(raison, into: &buf)
            
        }
    }
}


